// 基础防抖函数
function debounce(fn, delay) {
  let timer = null; // 闭包变量，保存计时器 ID
  return function(...args) {
    // 每次调用时，清除上一次的计时器
    clearTimeout(timer);
    // 设置新的计时器，延迟执行 fn
    timer = setTimeout(() => {
      fn.apply(this, args); // 正确传递 this 和参数
    }, delay);
  };
}

// 使用示例
const log = debounce((msg) => console.log(msg), 300);
log('第一次'); // 计时器被重置
log('第二次'); // 计时器被重置
log('第三次'); // 300ms 后输出 '第三次'

function debounce(fn, delay, options = {}) {
  const { leading = false, trailing = true } = options;
  let timer = null;
  let isLeadingCalled = false;

  function debounced(...args) {
    // leading 模式：第一次触发立即执行
    if (leading && !isLeadingCalled) {
      fn.apply(this, args);
      isLeadingCalled = true;
    }
    clearTimeout(timer);
    timer = setTimeout(() => {
      if (trailing) {
        fn.apply(this, args);
      }
      isLeadingCalled = false; // 重置，允许下一次 leading 触发
    }, delay);
  }

  // 取消功能
  debounced.cancel = function() {
    clearTimeout(timer);
    timer = null;
    isLeadingCalled = false;
  };

  return debounced;
}

// 使用示例
const save = debounce(() => console.log('保存'), 1000, { leading: true });
save(); // 立即输出 '保存'
save(); // 被忽略
save.cancel(); // 取消后续执行

